from jsonb_to_recordset('[{"id": "55149f7e2f5d4278", "url": "https://www.hyundaimotorgroup.com/ko/story/hyundai-motor-company-india-pune-smart-factory", "title": "인도에서 열어 가는 새로운 30년, 현대차 푸네 신공장", "company": "현대자동차그룹", "category": "스마트제조", "date": "2026-10-19", "topics": ["프레스 / 차체", "도장 / 의장", "품질 / 신뢰성"], "tags": ["프레스", "용접", "전착", "실링", "3C2B", "수밀"], "summary": "푸네 신공장에서 프레스·차체·도장·의장과 최종 검사까지 이어지는 제조 흐름을 소개한다. 패널 크랙 감지, 용접 후 3D 계측, 전처리·전착·실링·3코트 2베이크, 조립 이력과 수밀 검사를 다룬다.", "study": "설계한 형상이 실제 공정에서 어떻게 만들어지고, 조립 상태와 수밀·외관 품질을 어떻게 확인하는지 연결해서 읽는다."}, {"id": "c030192513e83de2", "url": "https://www.hyundaimotorgroup.com/ko/news/hyundai-motor-company-kia-eforest-tech-day-2026", "title": "현대차·기아, ‘이포레스트 테크데이 2026’ 개최", "company": "현대자동차그룹", "category": "스마트제조", "date": "2026-10-18", "topics": ["시험 / 가상개발", "품질 / 신뢰성"], "tags": ["SDF", "디지털 트윈", "AI", "자동화"], "summary": "소프트웨어 중심 공장 전환과 제조 신기술을 소개한다. 디지털 트윈으로 설비와 공정을 사전 검증하고, 제조 데이터를 관리하며 공장 업무용 AI를 활용하는 방향을 설명한다.", "study": "차량 가상개발과 공장 디지털 트윈의 대상을 구분하고, 사전 검증·데이터 추적·현장 피드백의 역할을 공부한다."}, {"id": "29e0143b79522473", "url": "https://www.hyundaimotorgroup.com/ko/news/hyundai-motor-company-the-all-new-tucson-tech-experience-day", "title": "현대차, ‘디 올 뉴 투싼 테크·익스피리언스 데이’ 개최", "company": "현대자동차그룹", "category": "프레스 / 차체", "date": "2026-10-09", "topics": ["차체 / 충돌", "도장 / 의장"], "tags": ["클램쉘 후드", "포지 형상 제어", "헤밍", "유닛 캠", "성형"], "summary": "클램쉘 후드와 사이드 아우터의 복잡한 디자인을 양산으로 구현한 성형 기술을 설명한다. 포지 형상 제어, 헤밍용 유닛 캠, 다방향 인장 제어와 다단 성형 공법을 소개한다.", "study": "디자인 의도와 성형성·표면 품질·접합 품질을 함께 만족시키는 과정에 집중한다. 후드는 클로저 부품과도 연결된다."}, {"id": "891991d74063c79f", "url": "https://www.hyundaimotorgroup.com/ko/news/hyundai-motor-company-all-new-tucson-debut", "title": "현대차, ‘디 올 뉴 투싼’ 최초 공개", "company": "현대자동차그룹", "category": "차체 / 충돌", "date": "2026-09-20", "topics": ["섀시 / NVH", "차량전자 / E/E"], "tags": ["글라스", "흡차음", "도어", "전원 이중화"], "summary": "신형 투싼의 상품성과 주요 기술을 소개한다. 도어 글라스 두께 증가와 대시 흡차음 보강, 충돌 후 도어 잠금 해제를 위한 전원 이중화 등을 다룬다.", "study": "도어와 글라스가 정숙성뿐 아니라 사고 후 탈출·구조와도 연결된다는 관점으로 읽는다."}, {"id": "329a2f6a1e571214", "url": "https://www.hyundaimotorgroup.com/ko/story/kia-evo-plant-pbv-advanced-manufacturing-solutions", "title": "화성 EVO Plant: PBV 시대에 함께 진화하는 첨단 제조 솔루션", "company": "현대자동차그룹", "category": "도장 / 의장", "date": "2026-09-09", "topics": ["프레스 / 차체", "스마트제조", "품질 / 신뢰성"], "tags": ["4-벅", "LSS 용접", "건식 도장", "후드 장착", "헤드램프 에이밍"], "summary": "화성 EVO Plant의 차체·도장·조립 기술을 구체적으로 소개한다. 4-벅 순차 조립, 비전 기반 자율 보정 장착, 건식 도장 부스와 소량 컬러 생산, 후드·엠블럼 장착과 외장 검사 자동화를 다룬다.", "study": "외장 형상 설계가 실제로 조립 가능한지, 부품 위치와 갭·단차를 어떻게 보정하고 검사하는지 함께 공부한다."}, {"id": "2cef7071f1331483", "url": "https://www.hyundaimotorgroup.com/ko/story/kia-pbv-production-hub-tech-day", "title": "PBV 생태계의 현재와 미래를 마주하다, 기아 PBV 생산 허브 테크 데이", "company": "현대자동차그룹", "category": "도장 / 의장", "date": "2026-09-09", "topics": ["프레스 / 차체", "스마트제조", "품질 / 신뢰성"], "tags": ["4-벅", "LSS 용접", "복합소재 후드", "조립", "단차", "비전"], "summary": "PBV의 유연 생산을 위한 4-벅 순차 조립과 L.S.S 레이저 용접, 복합소재 후드 장착, 크래시패드·헤드라이닝 자동 조립을 설명한다. 기사에는 현재 적용 기술과 향후 공장 도입 계획이 함께 있으므로 구분해서 읽는다.", "study": "구조적 접근 제약이 있는 접합부, 부품 장착 위치 보정, 조립 공정과 외관 품질의 관계를 공부한다."}, {"id": "5761f8d48ccc3a2e", "url": "https://www.hyundaimotorgroup.com/ko/story/hyundai-8th-elantra-first-drive", "title": "차급의 경계를 넘어서다, 디 올 뉴 아반떼", "company": "현대자동차그룹", "category": "열관리 / 충전", "date": "2026-08-31", "topics": ["차체 / 충돌", "섀시 / NVH"], "tags": ["AAF", "범퍼", "디플렉터", "언더커버", "공력"], "summary": "범퍼 코너 형상, 휠 디플렉터와 엔진룸 언더커버를 다듬어 공기 흐름을 개선했다. AAF는 엔진 냉각이 불필요할 때 공기 유입을 줄여 공기저항을 낮춘다.", "study": "그릴·AAF·라디에이터를 구분하고, 냉각 요구와 차량 항력을 함께 고려하는 이유를 설명한다."}, {"id": "4b84d5fbbfc3b25d", "url": "https://www.hyundaimotorgroup.com/ko/story/the-all-new-avante-tech-day", "title": "디 올 뉴 아반떼 테크 데이, 첨단 기술의 대중화로 글로벌 최고의 자리를 입증하다", "company": "현대자동차그룹", "category": "차체 / 충돌", "date": "2026-08-03", "topics": ["열관리 / 충전", "프레스 / 차체", "섀시 / NVH"], "tags": ["안전", "성형", "AAF", "언더커버", "공력"], "summary": "차체 안전 성능과 설계·성형 협업, 하이브리드 효율 개선을 다룬다. 차량 코너·휠 디자인, 세미 외장형 AAF와 풀 언더커버 등 공력 대책을 설명한다.", "study": "Cd 0.28→0.26은 여러 공력 개선의 종합 결과다. 특정 부품 하나의 단독 효과로 설명하지 않는다."}, {"id": "d658a4e36e79f553", "url": "https://www.hyundaimotorgroup.com/ko/news/hyundai-motor-company-new-grandeur-tech-popup-store-event", "title": "현대차, ‘더 뉴 그랜저 테크 팝업 스토어’ 행사 개최", "company": "현대자동차그룹", "category": "열관리 / 충전", "date": "2026-07-09", "topics": ["차체 / 충돌", "섀시 / NVH", "도장 / 의장"], "tags": ["AAF", "실링 가이드", "라디에이터", "공력", "냉각"], "summary": "더 뉴 그랜저 하이브리드 AAF의 실링 가이드로 주변 공기 누설을 줄이고 라디에이터 통과 유동을 개선한다. 에어커튼·휠 디플렉터·리어 범퍼 로워 커버도 함께 설명한다.", "study": "누설과 우회 유동을 줄여 냉각과 공력을 함께 개선하는 사례다. Cd 0.27→0.26을 실링 가이드만의 효과로 설명하지 않는다."}, {"id": "a9fdffd7c8937672", "url": "https://www.hyundaimotorgroup.com/ko/story/the-new-grandeur-development-story", "title": "최고의 자리에 안주하지 않는 혁신 리더, 더 뉴 그랜저 개발 스토리", "company": "현대자동차그룹", "category": "도장 / 의장", "date": "2026-07-09", "topics": ["차량전자 / E/E", "섀시 / NVH", "하이브리드"], "tags": ["스마트 비전 루프", "PDLC", "글라스", "차음 필름", "패키지"], "summary": "스마트 비전 루프에 투명도 조절 필름과 열차단 코팅·차음 필름을 적용하고 블라인드를 없애 공간을 확보했다. 전동식 에어벤트와 고객 의견을 반영한 설계 변경도 다룬다.", "study": "유리 면적·개방감·헤드룸·열차단·정숙성이 동시에 요구되는 사례로 읽는다."}, {"id": "a9da603cba3c3605", "url": "https://www.hyundaimotorgroup.com/ko/story/the-new-grandeur-hybrid-nvh-development-story", "title": "더 뉴 그랜저 하이브리드가 한 차원 향상된 안락함을 제공하는 이유", "company": "현대자동차그룹", "category": "섀시 / NVH", "date": "2026-07-09", "topics": ["하이브리드", "도장 / 의장"], "tags": ["P1 P2", "역위상 토크", "엔진 정지각", "EFC", "EIFC"], "summary": "P1·P2 모터의 역위상 토크 제어와 엔진 정지각 제어로 하이브리드의 진동과 소음을 줄이는 원리를 소개한다. 뒷좌석 거주성과 스테이 모드의 개발도 다룬다.", "study": "진동 발생원 제어와 외장·흡차음 부품의 전달 경로 대책을 구분한다. 음향 상쇄와 토크 상쇄를 같은 물리량으로 혼동하지 않는다."}, {"id": "20b8270ce52913aa", "url": "https://www.hyundaimotorgroup.com/ko/story/hyundai-motor-group-busan-mobility-show-2026", "title": "일상의 혁신부터 트랙의 열정까지: 현대차그룹 2026 부산모빌리티쇼", "company": "현대자동차그룹", "category": "SDV / IVI", "date": "2026-07-03", "topics": ["상품 / 사업전략", "차체 / 충돌"], "tags": ["플레오스 커넥트", "디지털 경험", "PBV", "마그마"], "summary": "현대차·기아·제네시스가 제시한 전동화와 디지털 경험을 살펴본다. 플레오스 커넥트 체험, PV5 라인업과 컨버전 모델, 마그마 GT 콘셉트와 GMR-001 전시를 소개한다.", "study": "차량 개발의 목표가 부품 성능뿐 아니라 고객 사용 경험으로 확장되는 흐름을 파악한다. 전시 콘셉트와 양산 적용을 구분한다."}, {"id": "ef385065fcaf4b0f", "url": "https://www.hyundaimotorgroup.com/ko/story/nova-lab-control-system-validation-hub", "title": "제어기 선행검증의 끝판왕, NOVA Lab", "company": "현대자동차그룹", "category": "시험 / 가상개발", "date": "2026-07-02", "topics": ["차량전자 / E/E", "품질 / 신뢰성"], "tags": ["와이어카", "선행 검증", "제어기", "통신", "시작차 이전"], "summary": "실제 차량처럼 제어기·전장 부품·와이어링 하네스를 연결한 와이어카로 시작차 제작 전에 기능과 통신을 검증하는 NOVA Lab을 소개한다. 테스트벤치와 실차 수준의 검증 환경을 다룬다.", "study": "시제품을 만든 뒤 문제를 찾는 것과 제작 이전에 인터페이스를 검증하는 것의 차이를 정리한다. 기존 목록의 게시일을 원문 기준으로 보완했다."}, {"id": "7a3d152b88f9b99e", "url": "https://www.hyundaimotorgroup.com/ko/story/driving-simulator-accelerating-vehicle-development", "title": "자동차 개발의 속도를 높이는 가상 환경 검증, 드라이빙 시뮬레이터", "company": "현대자동차그룹", "category": "시험 / 가상개발", "date": "2026-07-02", "topics": ["섀시 / NVH"], "tags": ["가상개발", "시뮬레이터", "노면", "시험", "해석"], "summary": "실제 노면 데이터와 차량 해석 모델을 결합해 부품 특성을 바꾸며 주행 성능을 평가하는 개발 방식을 소개한다. 시작차 제작 전부터 개발 의사결정을 지원한다.", "study": "모델과 실제 차량의 일치도를 확보하는 방법, 가상 시험과 실물 시험이 보완하는 관계를 읽는다."}, {"id": "48fae5541449e378", "url": "https://www.hyundaimotorgroup.com/ko/story/hyundai-motor-group-additive-manufacturing-solution-center-asmc", "title": "무엇이든 만들어 낸다, 현대차그룹 ‘적층 제조 솔루션 센터(AMSC)’", "company": "현대자동차그룹", "category": "스마트제조", "date": "2026-07-02", "topics": ["소재 / 경량화", "시험 / 가상개발"], "tags": ["적층제조", "3D 프린팅", "시제품", "후처리", "검사"], "summary": "설계부터 출력·후처리·검사까지 적층제조의 전 과정을 내부에서 수행하는 체계를 소개한다. 빠른 설계 변경, 다품종 소량 제작과 부품 복원 등에 활용한다.", "study": "시제품 제작 가능 조건과 공정별 제약, 제작 후 검증의 역할을 공부한다. 설계·해석만 수행한 W사 과제와 실제 제작한 다른 연구의 범위를 구분한다."}, {"id": "f7f6e7200f28dd8d", "url": "https://www.hyundaimotorgroup.com/ko/news/hyundai-motor-company-new-staria-electric-limousine-launch", "title": "현대차, ‘더 뉴 스타리아 일렉트릭·더 뉴 스타리아 리무진’ 출시", "company": "현대자동차그룹", "category": "차체 / 충돌", "date": "2026-04-23", "topics": ["열관리 / 충전", "도장 / 의장"], "tags": ["외장형 AAF", "파팅 라인", "충전구", "패키지"], "summary": "외장형 AAF와 전면 충전구를 최소한의 파팅 라인으로 구현했다. 전동화 기능과 차량의 외관 디자인, 실내 공간을 통합한 사례다.", "study": "새로운 기능을 외장에 배치할 때 생기는 분할선·배치·패키지 요구를 살펴본다."}, {"id": "f8c1a2776b7a608b", "url": "https://www.hyundaimotorgroup.com/ko/news/boulder-concept-world-premiere", "title": "‘볼더’ 콘셉트 세계 최초 공개", "company": "현대자동차그룹", "category": "차체 / 충돌", "date": "2026-04-02", "topics": ["상품 / 사업전략"], "tags": ["바디 온 프레임", "픽업트럭", "외장 디자인", "콘셉트카"], "summary": "바디 온 프레임 구조를 바탕으로 차세대 중형 픽업트럭의 디자인 방향성을 제시한 볼더 콘셉트를 소개한다. 견고한 차체와 기능 중심의 외장 구성을 함께 강조한다.", "study": "모노코크와 바디 온 프레임의 차이를 공부하고, 험로 사용 조건이 차체와 외장 부품 요구 조건에 미치는 영향을 생각한다. 콘셉트 모델이라는 범위를 지킨다."}, {"id": "155390d4bd33b4c8", "url": "https://www.hyundaimotorgroup.com/ko/news/hyundai-motor-group-international-hydrogen-fuel-cell-expo-2026-participation", "title": "현대차그룹, 〈국제 수소 & 연료전지 엑스포 2026〉 참가", "company": "현대자동차그룹", "category": "수소 / 연료전지", "date": "2026-03-17", "topics": ["도장 / 의장", "열관리 / 충전", "스마트제조"], "tags": ["HTWO", "수소 버너", "도장 오븐", "자동 충전"], "summary": "수소 모빌리티·충전·저장과 산업 활용 기술을 소개한다. 울산공장 도장 오븐을 시작으로 수소 버너를 확대 적용하려는 계획과 수소전기차 자동 충전 로봇을 다룬다.", "study": "차량의 친환경성과 생산 공정의 탈탄소화를 구분한다. 도장 오븐의 열원 전환에서 온도 제어와 도장 품질을 어떻게 확보할지 공부한다."}, {"id": "4ead518508313419", "url": "https://www.hyundaimotorgroup.com/ko/story/hyundai-motor-group-hybrid-technology-history-nactoy-2026", "title": "‘2026 북미 올해의 차’로 결실을 맺은 현대자동차그룹의 하이브리드 기술 발전사", "company": "현대자동차그룹", "category": "하이브리드", "date": "2026-02-24", "topics": ["전동화 구동", "섀시 / NVH"], "tags": ["TMED", "P1+P2", "하이브리드 변속기", "정숙성"], "summary": "초기 하이브리드부터 독자 시스템과 차세대 하이브리드까지의 발전을 설명한다. 성능·효율과 정숙성, 전동화 주행 감각을 함께 개선해 온 흐름을 정리한다.", "study": "기존 P0+P2와 P1+P2 공부 내용을 시대별 시스템 변화와 연결한다. 모터 배치, 동력 전달 경로와 NVH 제어의 역할을 나누어 이해한다."}, {"id": "f999b9adde14ae54", "url": "https://www.hyundaimotorgroup.com/ko/story/hyundai-motor-group-global-vehicle-safety-assessment-response", "title": "글로벌 자동차 안전 평가에 선제적으로 대응하는 현대차그룹", "company": "현대자동차그룹", "category": "차체 / 충돌", "date": "2026-02-06", "topics": ["시험 / 가상개발", "품질 / 신뢰성"], "tags": ["충돌시험", "NCAP", "보행자 보호", "사고 후 대응"], "summary": "국가별 신차 안전성 평가와 충돌 검증 체계를 소개한다. 탑승자·보행자 보호와 사고 후 대응까지 평가 범위가 넓어지는 흐름을 설명한다.", "study": "부품 설계 요구가 어떤 시험·평가와 연결되는지 이해한다. 구체적인 평가 기준을 면접에 인용할 때는 적용 연도와 원 규정을 별도로 확인한다."}, {"id": "2427c619dd025a7c", "url": "https://www.hyundaimotorgroup.com/ko/story/hyundai-palisade-nactoy-2026-key-reasons", "title": "전기차 강자들을 꺾은 팰리세이드, 북미 올해의 차에 선정된 결정적인 이유는?", "company": "현대자동차그룹", "category": "차체 / 충돌", "date": "2026-02-05", "topics": ["하이브리드", "섀시 / NVH", "상품 / 사업전략"], "tags": ["패밀리 SUV", "안전 평가", "하이브리드", "승차감"], "summary": "팰리세이드의 동력 성능·효율, 모터 기반 주행 제어, 실내 공간과 안전성을 종합적으로 설명한다. 충돌 안전 평가 결과와 사고 예방 사양도 함께 다룬다.", "study": "개별 부품의 성능이 가족용 SUV의 고객 가치로 어떻게 연결되는지 읽는다. 안전 평가의 기관·평가 연식과 차종 조건을 구분한다."}, {"id": "abdecb8806669349", "url": "https://www.hyundaimotorgroup.com/ko/news/hyundai-mobis-next-gen-display-global-dream-team", "title": "현대모비스, 차세대 디스플레이 선점 위해 ‘글로벌 드림팀’ 꾸렸다", "company": "현대자동차그룹", "category": "차량전자 / E/E", "date": "2026-02-03", "topics": ["SDV / IVI", "차체 / 충돌"], "tags": ["윈드쉴드", "글라스", "HWD", "광학 필름", "시인성"], "summary": "현대모비스가 시스템·광학·필름·차량용 유리 기업과 홀로그래픽 윈드쉴드 디스플레이 양산 협력 체계를 구축했다. 전면 유리를 정보 표시 공간으로 활용하고 운전석과 조수석의 화면을 분리하는 기술이다.", "study": "전면 유리가 시계 확보와 차음뿐 아니라 광학 기능도 담당하는 방향을 공부한다. 2029년 양산 목표인 개발 기술과 현재 양산 기술을 구분한다."}, {"id": "942ec07b47b8e158", "url": "https://www.hyundaimotorgroup.com/ko/story/hyundai-all-new-palisade-nactoy-2026", "title": "북미 올해의 차, 팰리세이드를 빚은 손길", "company": "현대자동차그룹", "category": "섀시 / NVH", "date": "2026-02-03", "topics": ["시험 / 가상개발", "차체 / 충돌"], "tags": ["도어 글라스", "차음 글라스", "흡음 타이어", "현지 시험"], "summary": "도어 글라스 두께 증가, 도어 픽스드 차음 글라스와 흡음 타이어를 통해 정숙성을 개선했다. 가혹한 실제 환경에서 수행하는 현지 개발 시험도 설명한다.", "study": "차량 시스템을 완성할 때 부품의 소음 차단과 실제 사용 환경 검증이 함께 필요하다는 관점으로 읽는다."}, {"id": "a7a9c2ae83d625d3", "url": "https://www.hyundaimotorgroup.com/ko/news/hyundai-kia-vision-pulse-obstacle-detection-safety-technology", "title": "현대차·기아, 장애물 너머까지 파악하는 주행 안전 기술, ‘비전 펄스’ 공개", "company": "현대자동차그룹", "category": "ADAS / 자율주행", "date": "2026-01-29", "topics": ["차량전자 / E/E", "품질 / 신뢰성"], "tags": ["UWB", "객체 위치", "비가시 영역", "실증"], "summary": "UWB 신호를 활용해 차량 주변 객체 위치를 파악하고 충돌 위험을 경고하는 기술을 공개했다. 산업 현장에서의 실증도 소개한다.", "study": "기존에 저장한 기사의 한국어 원문 게시일과 적용 조건을 보완했다. 카메라로 보는 기술과 통신을 이용한 위치 측정의 차이를 구분한다."}, {"id": "28bdb70e5ddb9a35", "url": "https://www.hyundaimotorgroup.com/ko/story/hyundai-motor-group-vision-pulse-driving-safety-technology", "title": "시야의 한계를 넘어서는 현대차그룹의 주행 안전 기술, ‘비전 펄스’", "company": "현대자동차그룹", "category": "ADAS / 자율주행", "date": "2026-01-29", "topics": ["차량전자 / E/E", "품질 / 신뢰성"], "tags": ["UWB", "비가시 영역", "객체 인식", "안전"], "summary": "초광대역 통신으로 장애물 뒤의 객체 위치까지 파악하는 비전 펄스의 원리와 활용을 설명한다. 차량과 객체가 신호를 주고받는 방식과 산업·통학 안전 적용을 소개한다.", "study": "카메라의 시야와 통신 기반 위치 인식의 역할을 구분한다. 상대 객체의 UWB 장치 등 적용 조건을 확인하고 모든 장애물을 무조건 탐지한다고 설명하지 않는다."}, {"id": "db946fb2a3862446", "url": "https://www.hyundaimotorgroup.com/ko/news/hyundai-wia-future-mobility-vision-ces-2026", "title": "현대위아, 미래 모빌리티 비전 제시…CES 2026 참가", "company": "현대자동차그룹", "category": "열관리 / 충전", "date": "2026-01-06", "topics": ["도장 / 의장", "차량전자 / E/E"], "tags": ["분산배치형 HVAC", "루프 에어컨", "스마트 벤트", "복사워머"], "summary": "탑승객별 체온과 취향을 반영하는 분산배치형 HVAC을 소개한다. 루프의 냉방, 하부의 복사워머와 움직임을 따라 바람을 보내는 스마트 벤트 등 실내 공간 변화에 맞춘 공조 배치를 다룬다.", "study": "공조 부품을 분산 배치할 때 패키지 공간, 열전달, 소음과 정비성을 함께 어떻게 고려할지 생각한다. 전시 기술을 양산 적용 완료로 표현하지 않는다."}, {"id": "bc8ce47e592060f6", "url": "https://www.hyundaimotorgroup.com/ko/news/CONT0000000000195946", "title": "현대위아, EV 통합열관리시스템 사업 확장 나서", "company": "현대자동차그룹", "category": "열관리 / 충전", "date": "2025-12-12", "topics": ["스마트제조", "구매 / 공급망"], "tags": ["통합 열관리", "양산", "PV5", "공조"], "summary": "현대위아의 전기차 통합 열관리 시스템 양산과 PV5 공급 현황을 소개한다. 부품 개발 이후 생산 라인과 협력사 공급 체계를 통해 실제 차량에 적용되는 흐름을 볼 수 있다.", "study": "성능을 확보한 설계안을 양산품으로 만들기 위해 필요한 공정 안정성과 품질 관리, 공급사 협업을 연결해 읽는다."}, {"id": "b5f971ef4b1dad06", "url": "https://www.hyundaimotorgroup.com/ko/news/CONT0000000000195714", "title": "기아, ‘더 기아 PV5’ 유럽 안전성 평가서 최고 안전 등급(★★★★★) 획득", "company": "현대자동차그룹", "category": "차체 / 충돌", "date": "2025-12-09", "topics": ["ADAS / 자율주행", "품질 / 신뢰성"], "tags": ["PV5 카고", "유로 NCAP 상용 밴", "능동안전", "차체 강성"], "summary": "PV5 카고가 유로 NCAP 상용 밴 평가에서 최고 등급을 획득한 사례다. 주행 안전성·충돌 방지·충돌 후 보호 시스템 평가와 차체 하부 보강 등 안전 설계를 소개한다.", "study": "상용 밴 평가의 최고 등급을 승용차 충돌 시험의 별점과 동일한 의미로 설명하지 않는다. 평가 항목과 적용 차종을 원문에서 확인한다."}, {"id": "1dd047d3b1cae0b5", "url": "https://www.hyundaimotorgroup.com/ko/story/CONT0000000000193387", "title": "미래를 앞당기는 혁신 제조기술, 이포레스트 테크데이 2025 현장을 가다", "company": "현대자동차그룹", "category": "스마트제조", "date": "2025-11-19", "topics": ["도장 / 의장", "품질 / 신뢰성", "시험 / 가상개발"], "tags": ["와이어링", "커넥터", "3D 스캐너", "PHM", "진동", "온도"], "summary": "와이어링 공급 자동화, 커넥터 체결 검사, 3D 스캐너 품질검사와 설비 고장 예측 등 제조 신기술을 설명한다. 2026년 행사 기사보다 개별 기술을 구체적으로 공부하기 좋다.", "study": "조립 불량 예방·검출과 설비 상태 진단을 구분하고, 진동·온도 데이터가 실제 공정에서 어떻게 쓰이는지 읽는다."}, {"id": "9c287df69e1a767d", "url": "https://www.hyundaimotorgroup.com/ko/story/CONT0000000000193032", "title": "차체 혁신의 미래를 그리는 연구원들의 축제, 2025 HMG 카바디 컨퍼런스", "company": "현대자동차그룹", "category": "프레스 / 차체", "date": "2025-11-14", "topics": ["차체 / 충돌", "소재 / 경량화", "도장 / 의장"], "tags": ["플렉시블 바디", "도어", "테일게이트", "LSS 용접", "복합재 격벽"], "summary": "PV5의 차체·도어·테일게이트 모듈화, 패널을 눌러 간극을 조절하는 LSS 레이저 용접, 경량 복합재 격벽 개발 사례를 소개한다. 강성·경량화·공간 효율과 다사양 대응을 함께 다룬다.", "study": "설계·소재·접합이 함께 차체 성능을 결정하는 사례로 읽는다. 외장 패널의 금형 공용화와 가니쉬 분할이 생산·수리 비용에 주는 영향도 공부한다."}, {"id": "78fb47ffa5d403ae", "url": "https://www.hyundaimotorgroup.com/ko/story/CONT0000000000188501", "title": "더 뉴 아이오닉 6, 보이지 않는 진화로 더 완벽한 이동 경험을 선사하다", "company": "현대자동차그룹", "category": "섀시 / NVH", "date": "2025-10-02", "topics": ["차체 / 충돌", "품질 / 신뢰성"], "tags": ["SDC3", "하이드로 G부시", "IDA", "진동", "풍절음"], "summary": "하이드로 G부시, SDC3와 IDA 등으로 주행 품질과 NVH를 개선한 사례를 설명한다. 진동 전달·강성·감쇠를 실제 차량 부품과 연결할 수 있다.", "study": "기존 직무공부의 SDC3·하이드로 부시·IDA 원리 설명과 함께 읽는다. 기사에 있는 수치·단위의 오기는 그대로 면접에 인용하지 않는다."}, {"id": "7b311282790f986f", "url": "https://www.hyundaimotorgroup.com/ko/story/CONT0000000000185186", "title": "패밀리 EV 세단을 다시 정의하다, 더 뉴 아이오닉 6", "company": "현대자동차그룹", "category": "열관리 / 충전", "date": "2025-09-04", "topics": ["차체 / 충돌", "섀시 / NVH"], "tags": ["듀얼모션 AAF", "덕테일 스포일러", "에어커튼", "에어로 휠", "공력"], "summary": "후드·램프·범퍼·스포일러를 바꾼 아이오닉 6의 디자인과 주행 성능을 설명한다. 듀얼모션 AAF, 덕테일 스포일러, 에어커튼과 에어로 휠을 통한 공력 설계를 구체적으로 소개한다.", "study": "외장 형상 변경이 스타일과 공력에 동시에 영향을 주는 사례로 활용한다. 공력 장치별로 어느 위치의 공기 흐름을 제어하는지 정리한다."}, {"id": "dcab9225480849a0", "url": "https://www.hyundaimotorgroup.com/ko/story/CONT0000000000183087", "title": "내구 레이스를 향한 제네시스의 거침없는 진격", "company": "현대자동차그룹", "category": "시험 / 가상개발", "date": "2025-08-18", "topics": ["차체 / 충돌", "상품 / 사업전략"], "tags": ["GMR-001", "내구 시험", "공력 설계", "시스템 통합"], "summary": "GMR-001 하이퍼카의 개발과 실전 준비 과정을 소개한다. 섀시와 엔진·하이브리드·변속기의 통합, 공력 개발과 서킷 시험이 완성차 개발로 이어지는 흐름을 볼 수 있다.", "study": "개별 부품 성능과 차량에 통합했을 때의 성능을 구분하고, 시험 데이터를 바탕으로 설계를 보완하는 과정을 살펴본다."}, {"id": "25fca9e67ff2a965", "url": "https://www.hyundaimotorgroup.com/ko/news/CONT0000000000181803", "title": "현대위아, 자동차 공조 시스템 시장 첫 진출", "company": "현대자동차그룹", "category": "열관리 / 충전", "date": "2025-07-25", "topics": ["섀시 / NVH", "시험 / 가상개발"], "tags": ["HVAC", "CRFM", "쿨링 모듈", "극한 온도 시험", "NVH"], "summary": "PV5에 공급하는 공조 시스템과 통합 열관리 시스템을 소개한다. HVAC과 쿨링 모듈의 패키지를 최적화하고 소음·진동을 줄였으며, 영상 65도와 영하 30도 등의 시험 조건을 다룬다.", "study": "라디에이터 주변 냉각 모듈이 공간과 NVH 요구를 함께 충족해야 한다는 점을 히트파이프 과제와 연결한다. 동일 부품을 개발한 경험처럼 확대하지 않는다."}, {"id": "4e0901bb8ffb4eca", "url": "https://www.hyundaimotorgroup.com/ko/story/CONT0000000000181529", "title": "현대차그룹 환경시험동, 극한의 환경에서도 흔들림 없는 열관리 성능을 확보하다", "company": "현대자동차그룹", "category": "시험 / 가상개발", "date": "2025-07-24", "topics": ["열관리 / 충전", "차량전자 / E/E"], "tags": ["환경 풍동", "냉각", "열해", "제상", "기후 재현"], "summary": "고온·저온·강설 환경 풍동에서 주행 부하와 기후를 재현해 냉각·열해·냉난방·제상 성능을 검증하는 과정을 설명한다. 반복 가능한 환경에서 얻은 시험 데이터가 시스템 개발에 반영된다.", "study": "해석의 경계조건이 시험에서는 온도·습도·풍속·부하 설정으로 어떻게 구현되는지 연결한다. 글라스의 시계 확보와 제상 평가도 함께 공부한다."}, {"id": "a636225697c3699c", "url": "https://www.hyundaimotorgroup.com/ko/story/CONT0000000000181587", "title": "정숙함을 넘어 감성적인 이동 경험을 완성하다, 현대자동차그룹의 NVH 기술 혁신", "company": "현대자동차그룹", "category": "시험 / 가상개발", "date": "2025-07-24", "topics": ["섀시 / NVH"], "tags": ["로드노이즈", "무향실", "몰입음향", "진동", "시험"], "summary": "로드노이즈 시험실과 몰입음향 스튜디오를 통해 소음·진동과 감성 품질을 개발하는 방법을 소개한다. 실제 가진 재현과 가상 평가를 함께 다룬다.", "study": "음원·전달 경로·응답을 나누어 문제를 분석하는 방법과 해석·시험 경험을 연결해 공부한다."}, {"id": "5730a7e6cc8b053b", "url": "https://www.hyundaimotorgroup.com/ko/story/CONT0000000000181016", "title": "더 기아 PV5의 바탕을 이루는 PBV 전용 플랫폼, ‘E–GMP.S’에 담긴 기술들", "company": "현대자동차그룹", "category": "차체 / 충돌", "date": "2025-07-23", "topics": ["전동화 구동", "소재 / 경량화"], "tags": ["E-GMP.S", "저상화", "풀 플랫 플로어", "전방 다중골격", "확장성"], "summary": "고객의 운용 환경을 반영한 PBV 전용 플랫폼 개발을 연구원 인터뷰로 설명한다. 운전석 위치와 저상 플로어, 공간 확장성과 충돌 안전을 함께 확보하는 설계를 다룬다.", "study": "실내 공간을 늘리는 요구와 충돌 하중을 지지하는 구조의 요구가 어떻게 함께 해결되는지 공부한다. 플랫폼 공용화와 바디 모듈화를 구분한다."}, {"id": "4ae5608141c53bf3", "url": "https://www.hyundaimotorgroup.com/ko/news/CONT0000000000180418", "title": "현대자동차, ‘아이오닉 6 N’ 세계 최초 공개", "company": "현대자동차그룹", "category": "열관리 / 충전", "date": "2025-07-10", "topics": ["차체 / 충돌", "섀시 / NVH"], "tags": ["고성능 전기차", "냉각", "공력", "차체", "서킷"], "summary": "모터스포츠와 롤링랩 데이터를 반영한 아이오닉 6 N을 공개한 기사다. 고성능 전동화 차량의 동력 성능, 주행 안정성과 특화 기능을 소개한다.", "study": "고성능 차량에서 냉각 공기 확보와 공력 성능의 절충을 공부한다. 기존에 저장한 기사의 한국어 원문 게시일을 보완했다."}, {"id": "5f62f791a7a54980", "url": "https://www.hyundaimotorgroup.com/ko/story/CONT0000000000174902", "title": "영감의 순간부터 컬러의 탄생까지, 제네시스 컬러의 매력", "company": "현대자동차그룹", "category": "도장 / 의장", "date": "2025-04-30", "topics": ["소재 / 경량화", "상품 / 사업전략"], "tags": ["외장 컬러", "CMF", "광택", "소재", "감성 품질"], "summary": "제네시스 콘셉트와 양산차의 외장 컬러가 만들어지는 배경을 설명한다. 빛과 각도에 따른 색감과 광택, 실내 소재와의 조화를 통해 디자인 의도를 구현하는 과정을 소개한다.", "study": "색상이 같아도 소재·표면·조명에 따라 다르게 보일 수 있다는 점을 외관 품질과 연결한다. 컬러 디자인 기사와 도장 공정 기술 자료의 범위를 구분한다."}, {"id": "d3b3e05b61fd8214", "url": "https://www.hyundaimotorgroup.com/ko/story/CONT0000000000173977", "title": "현대자동차그룹과 함께 즐기는 2025 서울모빌리티쇼", "company": "현대자동차그룹", "category": "상품 / 사업전략", "date": "2025-04-09", "topics": ["차체 / 충돌", "하이브리드", "수소 / 연료전지"], "tags": ["아이오닉 6", "디 올 뉴 넥쏘", "PV5", "외장 스타일"], "summary": "현대차·기아·제네시스의 전동화 라인업과 모빌리티 방향을 살펴본다. 더 뉴 아이오닉 6의 스타일 변경과 공력 성능 유지, 넥쏘와 PV5 등 다양한 사용 목적의 차량을 소개한다.", "study": "서로 다른 차급과 사용 목적이 외장 형상·공간·기능 요구를 어떻게 바꾸는지 비교한다. 신차 공개 행사에서의 설명과 상세 성능 검증 자료를 구분한다."}, {"id": "b432ad3694f60497", "url": "https://www.hyundaimotorgroup.com/ko/story/CONT0000000000172551", "title": "현대차그룹 제조기술 역량의 집약체, HMGMA를 소개합니다", "company": "현대자동차그룹", "category": "도장 / 의장", "date": "2025-03-27", "topics": ["프레스 / 차체", "스마트제조", "품질 / 신뢰성"], "tags": ["실러", "수밀", "샌딩", "도장 비전 검사", "조립"], "summary": "프레스부터 의장까지 HMGMA의 제조 기술을 소개한다. 실러 도포로 틈새를 메워 소음 차단과 수밀을 확보하고, 샌딩 자동화와 비전 검사로 도장 품질을 관리한다.", "study": "도장 공정이 색상뿐 아니라 실링·방수·소음 차단과도 연결된다는 점에 주목한다. 틈새 누설을 개선한 실험 경험과 연결해 읽는다."}, {"id": "03af52974c222924", "url": "https://www.hyundaimotorgroup.com/ko/news/hyundai-motor-group-metaplant-america-completion-ceremony", "title": "현대자동차그룹 메타플랜트 아메리카(HMGMA) 준공식 개최", "company": "현대자동차그룹", "category": "스마트제조", "date": "2025-03-26", "topics": ["도장 / 의장", "품질 / 신뢰성"], "tags": ["SDF", "도어 장착", "도장 비전 검사", "양산 품질"], "summary": "HMGMA의 소프트웨어 중심 생산 체계와 로봇 자동화를 공식 발표한 기사다. 고중량 도어 장착 자동화와 다수 이미지에 기반한 도장 검사, 제조 데이터 기반 이상 감지를 소개한다.", "study": "별도로 저장한 HMGMA 공정 해설 기사와 함께 읽고, 설계 목표가 생산 현장에서 어떤 측정과 검사로 보증되는지 정리한다."}, {"id": "f977e361dfc50e98", "url": "https://www.hyundaimotorgroup.com/ko/story/CONT0000000000171859", "title": "스마트한 배터리 셀 냉각 소재, 현대모비스의 진동형 히트파이프", "company": "현대자동차그룹", "category": "열관리 / 충전", "date": "2025-03-17", "topics": ["배터리 / BMS", "소재 / 경량화"], "tags": ["진동형 히트파이프", "상변화", "배터리 셀", "박형 구조"], "summary": "배터리 셀 사이의 좁은 공간에 배치할 수 있는 진동형 히트파이프를 소개한다. 밀봉된 내부의 냉매가 기화하며 진동·순환해 열을 전달하는 원리와 박형 구조의 장점을 설명한다.", "study": "본인 과제의 외부 공기 유동·핀 형상 개선과 이 기사의 내부 냉매 상변화 원리를 구분한다. 같은 히트파이프라는 이름만으로 기술을 동일시하지 않는다."}, {"id": "0a541cf9e267e5ea", "url": "https://www.hyundaimotorgroup.com/ko/story/CONT0000000000169921", "title": "미래 모빌리티의 혁신을 위한 복합소재", "company": "현대자동차그룹", "category": "소재 / 경량화", "date": "2025-02-20", "topics": ["도장 / 의장", "차체 / 충돌"], "tags": ["보디실러", "헤드램프", "무도장", "복합소재", "스포일러"], "summary": "초저비중 보디실러, 신소재 헤드램프와 ST1 루프 스포일러의 무도장 복합소재 성형을 소개한다. 형상뿐 아니라 소재와 공법도 경량화·외관 품질의 설계 변수임을 보여준다.", "study": "경량화와 강성·내충격성·표면 품질을 함께 고려하는 방법을 공부한다. 서로 다른 소재 구성과 적용 부품의 요구 성능을 구분한다."}, {"id": "5809182cd684cdf4", "url": "https://www.hyundaimotorgroup.com/ko/story/CONT0000000000069646", "title": "현대차그룹의 차체 충돌안전성 기술 역사를 돌아보다", "company": "현대자동차그룹", "category": "차체 / 충돌", "date": null, "topics": [], "tags": [], "summary": "에너지 흡수·승객 공간 보호·다중 하중 경로·배터리 보호", "study": "기존 학습 메모에서 가져온 기사입니다. 게시일은 재확인 전이며 원문에서 확인하세요."}, {"id": "3efda22a4fa70586", "url": "https://www.hyundaimotorgroup.com/ko/news/CONT0000000000186269", "title": "콘셉트 쓰리의 에어로 해치", "company": "현대자동차그룹", "category": "차체 / 충돌", "date": null, "topics": [], "tags": [], "summary": "에어로 해치·덕테일·외장 공력 형상", "study": "기존 학습 메모에서 가져온 기사입니다. 게시일은 재확인 전이며 원문에서 확인하세요."}, {"id": "b2d22d12da19e29e", "url": "https://www.hyundaimotorgroup.com/ko/story/CONT0000000000174589", "title": "차세대 하이브리드 테크 데이", "company": "현대자동차그룹", "category": "하이브리드", "date": null, "topics": [], "tags": [], "summary": "하이브리드 테크 데이·EFC·EIFC", "study": "기존 학습 메모에서 가져온 기사입니다. 게시일은 재확인 전이며 원문에서 확인하세요."}, {"id": "eb11b56090bec339", "url": "https://www.hyundaimotorgroup.com/ko/story/CONT0000000000173888", "title": "차세대 하이브리드 구조·모터와 변속기", "company": "현대자동차그룹", "category": "하이브리드", "date": null, "topics": [], "tags": [], "summary": "차세대 하이브리드의 모터 배치와 변속기", "study": "기존 학습 메모에서 가져온 기사입니다. 게시일은 재확인 전이며 원문에서 확인하세요."}, {"id": "6d5d32495f1a1979", "url": "https://www.hyundaimotorgroup.com/ko/story/namyang-digital-measurement-center-quality-improvement", "title": "외장 단차·NVH·수밀을 관리하는 디지털 측정센터", "company": "현대자동차그룹", "category": "품질 / 신뢰성", "date": null, "topics": [], "tags": [], "summary": "디지털 치수계측·갭·단차·수밀", "study": "기존 학습 메모에서 가져온 기사입니다. 게시일은 재확인 전이며 원문에서 확인하세요."}, {"id": "b85e110c045a2263", "url": "https:/